<script setup lang="ts">
import AdminRecycleDialog from './AdminRecycleDialog.vue'
import Paginator from '@/design-system/components/Paginator.vue'
import '@/features/management-shared/admin-lists.css'
import { computed, onMounted, ref, watch } from 'vue'
import SiteDialog from '@/features/management-shared/SiteDialog.vue'
import SiteSelect from '@/features/management-shared/SiteSelect.vue'
import type {SiteSelectPage} from '@/features/management-shared/site-select-types'
import { getAdminApi, roleLabel, type AdminRow } from './api'
const api=getAdminApi(), rows=ref<AdminRow[]>([]), query=ref(''), role=ref('teacher'), status=ref('all'), error=ref(''), busy=ref(false), loaded=ref(false), modal=ref(''), selected=ref<AdminRow>(), saved=ref('')
interface DeletePreview{name:string;counts:Record<string,number>;allowed:boolean;confirmation_token:string;retention_days:number;blocked_reason?:string}
const recycleOpen=ref(false),courseId=ref<string|number>(0),classId=ref<string|number>(0),deletePreview=ref<DeletePreview>(),confirmationName=ref('')
watch(courseId,()=>{classId.value=0})
const studentReady=computed(()=>Boolean(courseId.value&&classId.value))
function loadCourses(query:string,page:number){return api.get<SiteSelectPage>(`choices/courses/?${new URLSearchParams({q:query,page:String(page),...(courseId.value?{selected_id:String(courseId.value)}:{})})}`)}
function loadClasses(query:string,page:number){return api.get<SiteSelectPage>(`choices/classes/?${new URLSearchParams({q:query,page:String(page),course_id:String(courseId.value),...(classId.value?{selected_id:String(classId.value)}:{})})}`)}
async function requestDelete(row:AdminRow){selected.value=row;modal.value='delete';deletePreview.value=undefined;confirmationName.value='';error.value='';busy.value=true;try{deletePreview.value=await api.post<DeletePreview>(`users/${row.id}/delete-preview/`,{})}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function deleteUser(){if(!deletePreview.value?.allowed||confirmationName.value!==deletePreview.value.name||busy.value)return;busy.value=true;error.value='';try{await api.post(`users/${selected.value?.id}/delete/`,{confirmation:'DELETE',confirmation_name:confirmationName.value,confirmation_token:deletePreview.value.confirmation_token});rows.value=rows.value.filter(row=>row.id!==selected.value?.id);modal.value='';saved.value='账号已移入回收站，可在 14 天内恢复。'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
const countLabels:Record<string,string>={courses:'关联课程',owned_courses:'负责课程',collaborations:'协作关系',classes:'班级',enrollments:'选课关系',sessions:'作答会话',attempts:'作答记录',events:'过程事件',exports:'导出任务',students:'学生',banks:'题库',experiments:'实验'}
const form=ref({name:'',username:'',student_number:'',email:'',role:'teacher'})
const filtered=computed(()=>rows.value.filter(x=>x.role===role.value&&(status.value==='all'||x.is_active===(status.value==='active'))&&[x.name,x.username,x.student_number].join(' ').toLowerCase().includes(query.value.trim().toLowerCase())))
const page=ref(1),pageSize=20
const totalPages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/pageSize)))
const pageRows=computed(()=>filtered.value.slice((page.value-1)*pageSize,page.value*pageSize))
watch([role,query,status],()=>{page.value=1})
watch(totalPages,value=>{if(page.value>value)page.value=value})

async function load(){try{rows.value=(await api.get<{items:AdminRow[]}>('users/')).items;loaded.value=true}catch(e){error.value=(e as Error).message}}
onMounted(load)
function open(kind:string,row?:AdminRow){courseId.value=0;classId.value=0;selected.value=row;modal.value=kind;error.value='';form.value={name:row?.name||'',username:row?.username||'',student_number:row?.student_number||'',email:row?.email||'',role:row?.role||role.value}}
async function submit(){if(modal.value==='delete'){await deleteUser();return}if(modal.value==='create'&&form.value.role==='student'&&!studentReady.value){error.value='请选择启用中的课程和所属班级。';return}busy.value=true;error.value='';try{const id=selected.value?.id;await api.post(modal.value==='create'?'users/':`users/${id}/${modal.value==='edit'?'update':modal.value}/`,modal.value==='status'?{is_active:!selected.value?.is_active}:modal.value==='password'?{confirmation:'reset'}:{...form.value,...(modal.value==='create'&&form.value.role==='student'?{course_id:courseId.value,class_group_id:classId.value}:{})});modal.value='';saved.value='账号变更已保存。';await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template>
  <div class="eyebrow">ACCOUNTS / 账号管理</div><header class="heading"><div><h1>账号管理</h1><p>统一管理平台账号，清晰区分教师登录账号与学生学号。</p></div><div class="heading-actions"><button @click="recycleOpen=true">账号回收站</button><button class="primary" @click="open('create')">＋ 新增{{ roleLabel(role) }}</button></div></header>
  <p v-if="error && !modal" role="alert" class="error-block">{{ error }}</p><p v-if="saved" role="status" class="policy-note">{{ saved }}</p>
  <div class="stats"><div v-for="r in ['teacher','student','admin']" :key="r" class="stat"><div class="stat-top">{{ roleLabel(r) }}账号</div><strong>{{ rows.filter(x=>x.role===r).length }}</strong><small>全平台账号</small></div><div class="stat"><div class="stat-top">已停用账号</div><strong>{{ rows.filter(x=>!x.is_active).length }}</strong><small>保留历史关联</small></div></div>
  <section class="card admin-list"><div class="tabs"><button v-for="r in ['teacher','student','admin']" :key="r" :class="{active:role===r}" @click="role=r">{{ roleLabel(r) }} <em>{{ rows.filter(x=>x.role===r).length }}</em></button></div><div class="toolbar"><div class="search"><input v-model="query" aria-label="搜索账号" placeholder="搜索姓名、登录账号或学号"></div><select v-model="status" aria-label="账号状态"><option value="all">全部状态</option><option value="active">启用中</option><option value="disabled">已停用</option></select></div><div class="table-scroll"><table class="admin-list-table"><colgroup><col class="admin-list-col-name"><col class="admin-list-col-context"><col class="admin-list-col-summary"><col class="admin-list-col-status"><col class="admin-list-col-actions"></colgroup><thead><tr><th>姓名</th><th>{{ role==='student'?'学号':'登录账号' }}</th><th>关联课程</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in pageRows" :key="row.id"><td><div class="person"><span class="avatar">{{ row.name?.slice(0,1) }}</span><div><strong>{{ row.name }}</strong><small>{{ row.email || '未填写邮箱' }}</small></div></div></td><td class="account">{{ role==='student'?row.student_number:row.username }}</td><td>{{ row.course_count ?? 0 }} 门课程</td><td><span class="badge" :class="{gray:!row.is_active}">{{ row.is_active?'启用中':'已停用' }}</span></td><td><button class="link" @click="open('edit',row)">编辑</button><button class="link" @click="open('password',row)">重置密码</button><button class="link" :class="{danger:row.is_active}" @click="open('status',row)">{{ row.is_active?'停用':'启用' }}</button><button class="link danger" @click="requestDelete(row)">删除</button></td></tr><tr v-if="!filtered.length"><td colspan="5" class="empty">{{ loaded?'没有匹配的账号。':'正在加载账号…' }}</td></tr></tbody></table></div><Paginator :page="page" :total-pages="totalPages" @navigate="page=$event" /><div class="table-footer admin-list-footer">共 {{ filtered.length }} 个账号</div></section>
  <div class="policy-note"><div><strong>账号身份与课程授权分开管理</strong><br>停用保留教学与研究记录。协作教师的权限在所属课程中配置。</div></div>
  <SiteDialog class="admin-user-dialog" :open="Boolean(modal)" :title="modal==='delete'?'删除账号':modal==='create'?'新增'+roleLabel(role):modal==='edit'?'编辑账号':modal==='password'?'重置密码':selected?.is_active?'停用账号':'启用账号'" :subtitle="selected?.name || '填写真实账号信息'" @close="modal=''"><form id="admin-user-form" class="form-grid" @submit.prevent="submit"><template v-if="modal==='delete'"><p v-if="busy&&!deletePreview" role="status">正在读取删除影响…</p><template v-if="deletePreview"><p>账号及关联影响由服务器确认，移入回收站后保留 {{ deletePreview.retention_days }} 天恢复期。</p><dl class="detail-list"><div v-for="(count,key) in deletePreview.counts" :key="key"><dt>{{ countLabels[key]||key }}</dt><dd>{{ count }}</dd></div></dl><p v-if="!deletePreview.allowed" class="error-block">{{ deletePreview.blocked_reason||'该账号当前不能删除。' }}</p><label v-else class="field">输入 {{ deletePreview.name }} 确认删除<input v-model="confirmationName" name="confirmation_name" autocomplete="off" required></label></template></template><template v-if="modal==='create'||modal==='edit'"><label class="field">姓名<input v-model="form.name" name="name" required></label><label v-if="form.role!=='student'" class="field">登录账号<input v-model="form.username" name="username" required autocomplete="off"></label><label v-else class="field">学号<input v-model="form.student_number" name="student_number" required :disabled="modal==='edit'"></label><template v-if="modal==='create'&&form.role==='student'"><SiteSelect v-model="courseId" name="course_id" label="课程" placeholder="请选择启用中的课程" searchable :load-options="loadCourses" /><SiteSelect v-model="classId" name="class_group_id" label="班级" placeholder="请选择所属班级" searchable :load-options="loadClasses" :dependency-key="courseId" :disabled="!courseId" /></template><label class="field admin-user-email">邮箱<input v-model="form.email" name="email" type="email"></label></template><div v-if="modal==='create'||modal==='password'" class="admin-user-password-rule"><p>初始密码为 S + {{ form.role==='student'?'学号':'登录账号' }}，首次登录后提醒修改。</p><p v-if="modal==='password'">确认重置 {{ selected?.name }}（{{ form.role==='student'?form.student_number:form.username }}）的密码？</p></div><p v-if="modal==='status'">{{ selected?.is_active?'停用后该账号不能再登录，已有课程和历史记录保留。':'启用后恢复账号登录能力，课程授权保持不变。' }}</p><p v-if="error" role="alert" class="error-block">{{ error }}</p></form><template #footer><button @click="modal=''">取消</button><button class="primary" type="submit" form="admin-user-form" :disabled="busy||(modal==='create'&&form.role==='student'&&!studentReady)||(modal==='delete'&&(!deletePreview?.allowed||confirmationName!==deletePreview?.name))">{{ busy?'正在保存…':modal==='delete'?'确认删除':modal==='password'?'确认重置':'确认保存' }}</button></template></SiteDialog>
  <AdminRecycleDialog :open="recycleOpen" kind="user" @close="recycleOpen=false" @changed="load" />
</template>

<style>
.admin-user-dialog .form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px 18px}.admin-user-dialog .admin-user-email,.admin-user-dialog .admin-user-password-rule,.admin-user-dialog .form-grid>p,.admin-user-dialog .detail-list{grid-column:1/-1}.admin-user-dialog .admin-user-password-rule{color:#64758b;font-size:12px;line-height:1.6}.admin-user-dialog .admin-user-password-rule p{margin:0}.management-workspace .management-dialog.admin-user-dialog .modal-head{padding:20px 24px 14px}.management-workspace .management-dialog.admin-user-dialog .modal-content{padding:16px 24px}.management-workspace .management-dialog.admin-user-dialog .modal-footer{padding:14px 24px}.admin-user-dialog .field{gap:6px}.admin-user-dialog .site-select{gap:6px}.admin-user-dialog .field input{min-height:40px}.admin-user-dialog .site-select__trigger{min-height:40px}.admin-user-dialog .site-select__list{max-height:160px}@media(max-width:600px){.admin-user-dialog .form-grid{grid-template-columns:1fr}.management-workspace .management-dialog.admin-user-dialog .modal-content{padding:16px}}
@media(min-width:701px) and (min-height:650px){.management-workspace .management-dialog.admin-user-dialog,.management-workspace .management-dialog.admin-user-dialog .modal-content{overflow:visible}}
</style>
